#!/usr/bin/env python3
"""
Deep inspection script for the last 24h transcripts and sidecar activity.
"""

import json
import os
import re
from datetime import datetime, timezone, timedelta
from pathlib import Path

PLUGIN_DIR = Path("/Users/mcneillm/Documents/Projects/bug-fixer-loop-plugin")
CONFIG_PATH = PLUGIN_DIR / ".agents/plugins/bug-fixer-loop-workspace/config.json"
TMP_DIR = PLUGIN_DIR / ".agents/plugins/bug-fixer-loop-workspace/tmp"
DISPATCHES_DIR = PLUGIN_DIR / ".agents/plugins/bug-fixer-loop-workspace/dispatches"
CLAIMS_DIR = PLUGIN_DIR / ".agents/plugins/bug-fixer-loop-workspace/claims"
BRAIN_DIR = Path.home() / ".gemini/antigravity/brain"
SIDECAR_BASE = Path.home() / ".gemini/antigravity/sidecar_data"

CUTOFF_24H = datetime.now(timezone.utc) - timedelta(hours=24)
cutoff_ts = CUTOFF_24H.timestamp()

# 1. Discover all transcripts
transcripts = []
for conv_dir in BRAIN_DIR.iterdir():
    if not conv_dir.is_dir():
        continue
    t_file = conv_dir / ".system_generated/logs/transcript.jsonl"
    if not t_file.exists():
        continue
    if t_file.stat().st_mtime < cutoff_ts:
        continue
    try:
        with open(t_file, "r", encoding="utf-8", errors="replace") as f:
            head = f.read(3000)
        keywords = [
            "bug-fixer", "Bug Fixer", "bug-fixer-engineering", "bug-fixer-triage",
            "Fix #", "Triage:", "bug-fixer:engineer:needs-fix",
            "engineering_dispatcher", "triage_dispatcher", "architect_dispatcher",
            "matthewmcneill/bug-fixer-loop-plugin"
        ]
        if any(kw in head for kw in keywords):
            transcripts.append(t_file)
    except Exception:
        pass

print(f"Total matching transcripts: {len(transcripts)}")

sessions = []
for t_file in transcripts:
    conv_id = t_file.parents[2].name
    lines = []
    with open(t_file, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    lines.append(json.loads(line))
                except:
                    pass

    if not lines:
        continue

    first_step = lines[0]
    last_step = lines[-1]

    # Identify target repo, role, issue/PR, outcome
    repo = None
    role = "unknown"
    issue_num = None
    pr_num = None
    prompt_text = ""
    error_messages = []

    for item in lines:
        if item.get("type") == "ERROR_MESSAGE":
            error_messages.append(item.get("error", ""))
        if item.get("type") == "USER_INPUT" and not prompt_text:
            prompt_text = item.get("content", "")

    # Check repo
    if "bug-fixer-loop-plugin" in prompt_text:
        repo = "bug-fixer-loop-plugin"
    elif "esp32-app-foundation" in prompt_text:
        repo = "esp32-app-foundation"

    if "bug-fixer-triage" in prompt_text or "Triage:" in prompt_text:
        role = "triage"
    elif "bug-fixer-engineering" in prompt_text or "Fix #" in prompt_text:
        role = "engineering"
    elif "bug-fixer-architect" in prompt_text or "Architect" in prompt_text or "PR Review" in prompt_text:
        role = "architect"
    elif "bug-fixer-trajectory-review" in prompt_text:
        role = "trajectory"

    # Extract issue or PR
    m_issue = re.search(r"[Ff]ix\s+#?(\d+)|issue\s+#?(\d+)|Issue\s+#?(\d+)", prompt_text)
    if m_issue:
        for g in m_issue.groups():
            if g:
                issue_num = int(g)
                break
    m_pr = re.search(r"PR\s+#?(\d+)|pull\s+#?(\d+)", prompt_text)
    if m_pr:
        for g in m_pr.groups():
            if g:
                pr_num = int(g)
                break

    # Look at tool calls and outputs
    commands_run = []
    files_modified = []
    last_model_response = ""
    for item in lines:
        if item.get("type") == "PLANNER_RESPONSE":
            content = item.get("content") or ""
            if content:
                last_model_response = content
            for tc in item.get("tool_calls") or []:
